"""Build bilingual guide pages and enrich homepages. Python 3 standard library only."""
from pathlib import Path
from html import escape
from resource_library import gallery
import json,re,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1];DIST=ROOT/'dist'
ORIGIN='https://photo-craft.io'
PAGES=json.loads((ROOT/'content/pages.json').read_text());BY_SLUG={p['slug']:p for p in PAGES}
T={
'en':{'home':'Home','guides':'Guides','download':'Download','compare':'Compare','community':'Community','verified':'Sources checked: Oct 10, 2026','independent':'Independent guide · Early alpha','toc':'ON THIS PAGE','sources':'Sources & scope','scope':'Written from official documentation and editorial guidance. Not an exhaustive compatibility test. Menu names and behavior can change between releases.','related':'Continue learning','read':'Read the guide →','search':'Search guides, e.g. PSD or Windows','count':'guides','empty':'No matching guides. Try “install”, “PSD” or “Windows”.','foot':'Independent resource hub. Not affiliated with ArtCraft or Adobe.','hubtitle':'A little guidance. A lot more creating.','hubintro':'Install with confidence, learn your first workflow, and find the next step when something does not behave as expected.','early':'PhotoCraft is early alpha. Use copies of important documents and verify saved results.','review':'Official material, practical steps and clear limitations.'},
'zh':{'home':'首页','guides':'教程中心','download':'下载中心','compare':'功能对比','community':'社区','verified':'资料核对：2026 年 10 月 10 日','independent':'独立指南 · 早期 Alpha','toc':'本页目录','sources':'来源与适用范围','scope':'依据官方文档与本站编辑建议整理，不是全面兼容性实测。菜单名称和行为可能随版本变化。','related':'继续学习','read':'阅读教程 →','search':'搜索教程，如：PSD、安装、Windows','count':'篇指南','empty':'未找到相关教程，试试“安装”“PSD”或“Windows”。','foot':'独立资源站，与 ArtCraft 或 Adobe 无隶属关系。','hubtitle':'少一点摸索，多一点创作。','hubintro':'从选择安装包、完成第一个作品，到检查兼容性和解决常见问题，按你的下一步找到指南。','early':'PhotoCraft 处于早期 Alpha。重要文档请使用副本，并检查保存结果。','review':'官方资料、实用步骤与清晰的能力边界。'}}
def route(slug='',lang='en'):return ('/zh/' if lang=='zh' else '/')+(slug.strip('/')+'/' if slug else '')
def link(slug,lang,label=None):return f'<a href="{route(slug,lang)}">{escape(label or BY_SLUG[slug]["title"][lang])} ↗</a>'
def header(lang,slug):
 t=T[lang];other='zh' if lang=='en' else 'en'
 return f'''<header class="topbar"><div class="container nav"><a class="brand" href="{route('',lang)}"><span class="logo">◇</span>PhotoCraft</a><nav class="navlinks" aria-label="{'Main navigation' if lang=='en' else '主导航'}"><a href="{route('guides',lang)}">{t['guides']}</a><a href="{route('plugins',lang)}">{'插件与集成' if lang=='zh' else 'Plugins & integrations'}</a><a href="{route('templates',lang)}">{'模板与素材' if lang=='zh' else 'Templates & assets'}</a><a href="{route('download',lang)}">{t['download']}</a><a href="{route('',lang)}#compare">{t['compare']}</a><a href="{route('',lang)}#community">{t['community']}</a></nav><div class="nav-actions"><nav class="language-switch" aria-label="Language"><a href="{route(slug,'zh')}" lang="zh-CN" hreflang="zh-CN" {'aria-current="page"' if lang=='zh' else ''} data-language="zh">中文</a><a href="{route(slug,'en')}" lang="en" hreflang="en" {'aria-current="page"' if lang=='en' else ''} data-language="en">EN</a></nav><button class="menubtn" aria-label="{'Open menu' if lang=='en' else '展开导航'}" aria-expanded="false" aria-controls="mobile-nav">☰</button></div></div><nav class="mobile-nav" id="mobile-nav" aria-label="{'Mobile navigation' if lang=='en' else '移动导航'}"><a href="{route('guides',lang)}">{t['guides']}</a><a href="{route('plugins',lang)}">{'插件与集成' if lang=='zh' else 'Plugins & integrations'}</a><a href="{route('templates',lang)}">{'模板与素材' if lang=='zh' else 'Templates & assets'}</a><a href="{route('download',lang)}">{t['download']}</a><a href="{route('',lang)}#compare">{t['compare']}</a><a href="{route('',lang)}#community">{t['community']}</a></nav></header>'''
def shell(slug,lang,title,intro,body):
 t=T[lang];url=ORIGIN+route(slug,lang);htmllang='zh-CN' if lang=='zh' else 'en'
 meta=f'<link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{ORIGIN+route(slug)}"><link rel="alternate" hreflang="zh-CN" href="{ORIGIN+route(slug,"zh")}"><link rel="alternate" hreflang="x-default" href="{ORIGIN+route(slug)}">'
 return f'''<!doctype html><html lang="{htmllang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | PhotoCraft Resource Hub</title><meta name="description" content="{escape(intro,quote=True)}"><meta name="theme-color" content="#f7f6f2"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(intro,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:type" content="article"><link rel="icon" href="/icon.svg">{meta}<link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/content.css"><script src="/assets/content.js" defer></script></head><body>{header(lang,slug)}<main class="container"><div class="crumbs"><a href="{route('',lang)}">{t['home']}</a><span>/</span><a href="{route('guides',lang)}">{t['guides']}</a>{('<span>/</span><span>'+escape(title)+'</span>') if slug!='guides' else ''}</div>{body}</main><footer class="container article-footer"><div class="footer-top"><a class="brand" href="{route('',lang)}">PhotoCraft</a><div class="footer-links"><a href="{route('guides',lang)}">{t['guides']}</a><a href="{route('download',lang)}">{t['download']}</a><a href="https://github.com/storytold/photocraft" target="_blank" rel="noopener noreferrer">Official GitHub ↗</a></div></div><p class="source-note">© 2026 PhotoCraft Resource Hub · {t['foot']}</p></footer></body></html>'''
def heading(lang,title,intro,category,checked=None):
 t=dict(T[lang]);t["verified"]=(f"Sources checked: {checked}" if lang=="en" else f"资料核对：{checked}") if checked else t["verified"];return f'<div class="article-heading"><div class="overline">{escape(category)}</div><h1>{escape(title)}</h1><p class="dek">{escape(intro)}</p><div class="article-meta"><span>{t["verified"]}</span><span>{t["independent"]}</span></div></div>'
for lang in ['en','zh']:
 t=T[lang]
 for p in PAGES:
  toc=''.join(f'<a href="#{s["id"]}">{escape(s["title"][lang])}</a>' for s in p['sections'])
  sections=''.join(f'<section id="{s["id"]}"><h2>{escape(s["title"][lang])}</h2>{s["body"][lang]}</section>' for s in p['sections'])
  refs=''.join(f'<li><a href="{r["url"]}" target="_blank" rel="noopener noreferrer">{escape(r["label"])}</a></li>' for r in p['sources'])
  body=heading(lang,p['title'][lang],p['intro'][lang],p['category'][lang],p.get('checked'))+f'<div class="reading-layout"><aside class="toc"><strong>{t["toc"]}</strong>{toc}<a href="#sources">{t["sources"]}</a></aside><article class="article-body">{sections}<section class="sources" id="sources"><h2>{t["sources"]}</h2><p>{t["scope"]}</p><ul>{refs}</ul></section></article></div><section class="related"><h2>{t["related"]}</h2><div class="related-links">'+''.join(link(s,lang) for s in p['related'])+'</div></section>'
  if p['slug']=='templates':body=body.replace('<div class="reading-layout">',gallery(lang)+'<div class="reading-layout">',1)
  path=DIST/route(p['slug'],lang).lstrip('/')/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(shell(p['slug'],lang,p['title'][lang],p['intro'][lang],body))
 cards=''.join(f'<a class="guide-card" href="{route(p["slug"],lang)}" data-search="{escape((p["title"][lang]+" "+p["intro"][lang]+" "+p["category"][lang]).lower(),quote=True)}"><div class="overline">{p["category"][lang]}</div><h2>{p["title"][lang]}</h2><p>{p["intro"][lang]}</p><span class="read">{t["read"]}</span></a>' for p in PAGES)
 body=heading(lang,t['hubtitle'],t['hubintro'],'THE FIELD GUIDE / PHOTOCRAFT')+f'<div class="library-tools"><label class="search"><span aria-hidden="true">⌕</span><input id="guide-search" type="search" placeholder="{t["search"]}" aria-label="{t["search"]}"></label><span class="count" aria-live="polite"><span id="guide-count">{len(PAGES)}</span> {t["count"]}</span></div><div class="guide-grid">{cards}</div><p id="guide-empty" class="no-results" hidden>{t["empty"]}</p>'
 path=DIST/route('guides',lang).lstrip('/')/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(shell('guides',lang,t['hubtitle'],t['hubintro'],body))
 # Extend home with a feature gallery, task-led guides and a dated release summary.
 home=(ROOT/f'content/templates/home-{lang}.html').read_text()
 home=home.replace('</head>','<link rel="stylesheet" href="/assets/content.css"></head>')
 home=home.replace('href="#installation"',f'href="{route("guide",lang)}"').replace('href="#download"',f'href="{route("download",lang)}"')
 if lang=='en':home=home.replace('<a href="#community">Resources & community</a>',f'<a href="{route("guides",lang)}">Guides & tutorials</a>')
 else:home=home.replace('<a href="#community">资源与社区</a>',f'<a href="{route("guides",lang)}">教程中心</a>')
 stories=[('adjustments',('Adjust color. Keep your original.','调整颜色，保留原图。'),('Explore adjustment layers and compare edits without merging your original photo.','了解调整图层，在不合并原照片的情况下比较修改效果。'),'guide#adjust'),('masks',('Make an edit where it matters.','让修改只作用于需要的区域。'),('Understand why masks, clipping and layer relationships matter when exchanging a PSD.','了解蒙版、剪贴和图层关系，以及 PSD 交换时应检查的细节。'),'compatibility/psd'),('export-light',('Save a project. Share an image.','保存项目，分享成品。'),('Learn the difference between an editable document and an exported PNG or JPEG.','区分可编辑项目与导出的 PNG 或 JPEG，完成保存与复核。'),'guide#save')]
 figures=''
 for name,titles,descs,target in stories:
  slug,_,anchor=target.partition('#');dest=route(slug,lang)+('#'+anchor if anchor else '')
  figures+=f'<figure class="feature-story"><img src="/assets/photocraft-{name}.jpg" alt="{escape(titles[0 if lang=="en" else 1])}" width="1600" height="1000" loading="lazy"><figcaption><h3>{titles[0 if lang=="en" else 1]}</h3><p>{descs[0 if lang=="en" else 1]}</p><a href="{dest}">{t["read"]}</a></figcaption></figure>'
 learning=''.join(f'<a href="{route(s,lang)}"><span>{BY_SLUG[s]["title"][lang]}</span><span>↗</span></a>' for s in ['guide','download','compatibility/psd','troubleshooting'])
 extra=f'''<section class="learn-section" id="learn"><div class="section-title"><div><div class="overline">EXPLORE / LEARN / CREATE</div><h2>{'See the tools. Learn the workflow.' if lang=='en' else '看懂工具，学会操作。'}</h2></div><a class="text-link" href="{route('guides',lang)}">{t['guides']} ↗</a></div><div class="feature-grid">{figures}</div><p class="source-note">{'Official PhotoCraft screenshots · public-domain artwork · examples, not a compatibility guarantee.' if lang=='en' else 'PhotoCraft 官方截图 · 公有领域作品 · 示例不代表所有文件的兼容性。'}</p><div class="learning-banner"><div><div class="overline">THE FIELD GUIDE</div><h2>{'Your next step,<br>made clearer.' if lang=='en' else '每个下一步，<br>都有实用指南。'}</h2><p>{t['review']}</p><a class="text-link" href="{route('guides',lang)}">{f'Browse all {len(PAGES)} guides →' if lang=='en' else f'浏览全部 {len(PAGES)} 篇指南 →'}</a></div><div class="learning-links">{learning}</div></div><div class="release-strip"><div><span class="tag">v0.6.0</span> &nbsp; {'Release snapshot' if lang=='en' else '版本快照'}<p>{'Checked Oct 10, 2026 · See what changed and how to verify an upgrade.' if lang=='en' else '2026.10.10 核对 · 了解变化，并在升级后检查关键工作流。'}</p></div><a href="{route('releases',lang)}">{'Read release highlights ↗' if lang=='en' else '阅读更新摘要 ↗'}</a></div></section>'''
 home=home.replace('<section class="section" id="download">',extra+'<section class="section" id="download">',1)
 resources=[('plugins','Plugins & integrations','插件与集成','Official WASM filters and community tools.','官方 WASM 滤镜与社区工具。'),('templates','Templates & resources','模板与素材','14 original assets: layered PSD, PNG textures and LUTs.','14 份原创资源：分层 PSD、PNG 纹理与 LUT。'),('guides/luts','LUTs & color presets','LUT 与调色预设','Explore color looks and learn how to test them.','寻找调色风格，了解测试方法。'),('guides/comfyui','ComfyUI workflows','ComfyUI 工作流','Connect images, selections and AI workflows.','连接图像、选区与 AI 工作流。')]
 resource_cards=''.join(f'<a class="guide-card" href="{route(slug,lang)}"><div class="overline">PHOTOCRAFT RESOURCES</div><h3>{ze if lang=="zh" else en}</h3><p>{zd if lang=="zh" else ed}</p><span class="read">{t["read"]}</span></a>' for slug,en,ze,ed,zd in resources)
 resource_block=f'<div class="resource-library" id="resources"><div class="section-title"><div><div class="overline">EXTEND YOUR WORKFLOW</div><h2>{"Resources for your next project" if lang=="en" else "为下一个作品寻找资源"}</h2></div></div><p class="source-note">{"Original downloads, official documentation and community tools · application compatibility is labeled per resource." if lang=="en" else "原创下载、官方文档与社区工具 · 每项资源均注明兼容性验证范围。"}</p><div class="guide-grid">{resource_cards}</div><p><a class="text-link" href="{route('compatibility/photoshop-plugins',lang)}">{"Do Photoshop plugins work in PhotoCraft? →" if lang=="en" else "Photoshop 插件能在 PhotoCraft 中使用吗？ →"}</a></p></div>'
 home=re.sub(r'<div class="future">.*?</section>',resource_block+'</section>',home,count=1,flags=re.S)

 path=DIST/('zh/index.html' if lang=='zh' else 'index.html');path.write_text(home)
 if lang=='en':
  (DIST/'en/index.html').write_text(home.replace('src="photocraft-hero.webp"','src="../photocraft-hero.webp"').replace('href="icon.svg"','href="../icon.svg"'))
urls=[route('',lang) for lang in ['en','zh']]+[route(slug,lang) for lang in ['en','zh'] for slug in ['guides']+[p['slug'] for p in PAGES]]
ns='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',ns);xml=ET.Element('{'+ns+'}urlset')
for url in urls:
 entry=ET.SubElement(xml,'{'+ns+'}url');ET.SubElement(entry,'{'+ns+'}loc').text=ORIGIN+url
ET.ElementTree(xml).write(DIST/'sitemap.xml',encoding='utf-8',xml_declaration=True)
(DIST/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
print(f'Built {len(PAGES)*2} article pages, 2 guide hubs, 3 home routes and sitemap.')
from seo import optimize
optimize(ROOT, ORIGIN)
